// GATE S13-own (RUN3 WP B5): events RadUI writes carry a VTIMEZONE generated by calendar/tz.js (Intl only); the
// server's own generator is not relied on any more. Against a throwaway Radicale (tests/roundtrip/run.sh):
//   (a) 40 events per zone, written by the REAL item path (createItem -> save), PUT, GET: Radicale keeps a usable
//       VTIMEZONE (it re-serialises it: compared by instants, not bytes) and the app's embedded-zone read path
//       (icalview.js, class `embedded`) gives the Intl instant, gaps and overlaps included;
//   (b) a 17-year yearly series from 2024 and the matrix of wall times 2024-2040 against the served zone, and the
//       served zone against the zone of the text that was sent;
//   (c) two 10-year weekly series (Sunday 02:30 / 00:30), occurrence by occurrence;
//   (d) Europe/Paris five times, in different years (the intermittent server-generated Paris: see docs/roundtrip.md);
//   (e) a foreign (wrong) VTIMEZONE seen first by the server does not affect an item that carries ours.
// No browser; a few hundred small requests per zone.
import test from "node:test";
import assert from "node:assert/strict";
import { createItem, openItem } from "../../src/js/model/item.js";
import { SKIP } from "./lib.mjs";
import { countingEnv, newCalendar } from "./evlib.mjs";
import { GATE_ZONES, HOUR, MIN, eventWalls, intlOffset, matrixWalls, refInstant, runnerZone } from "./tzgate.mjs";

const env = SKIP ? null : countingEnv();
const it = (name, fn) => test(name, { skip: SKIP }, fn);
const NOW = new Date("2026-11-12T10:00:00Z");
const stamp = (ms) => new Date(ms).toISOString().slice(0, 19) + "Z";
const zonedSpec = (iso, tzid) => ({ kind: "zoned", iso, tzid });
const gateZones = [...new Set([...GATE_ZONES, runnerZone()])];
let seq = 0;

/** Text of a new event written by the app's own path (so with our VTIMEZONE). */
function newEventText(tz, startIso, { rrule, plusMs = HOUR } = {}) {
  const endIso = new Date(Date.parse(startIso + "Z") + plusMs).toISOString().slice(0, 19);
  const fields = { summary: "Gate event", start: zonedSpec(startIso, tz), end: zonedSpec(endIso, tz), ...(rrule ? { rrule } : {}) };
  const item = createItem("event", fields, { uid: `own-${seq++}-${Date.now().toString(36)}@example.org` });
  const out = item.save({ now: NOW });
  return { text: out.text, tzAdded: item.tzAdded };
}

async function putAndOpen(col, name, text) {
  const href = `${col}${name}.ics`;
  await env.client.putItem(href, text, { create: true });
  const served = await env.client.getItem(href);
  return { href, served: served.text, item: openItem(served.text, "event") };
}

/** The unfolded lines of the VTIMEZONE block, sorted (Radicale re-serialises it: order and folding may change). */
const vtzLines = (t) => {
  const lf = t.replace(/\r\n/g, "\n").replace(/\n[ \t]/g, "");
  const m = /BEGIN:VTIMEZONE\n[\s\S]*?\nEND:VTIMEZONE/.exec(lf);
  return m ? m[0].split("\n").sort().join("\n") : "";
};
const vtimezoneCount = (t) => (t.match(/^BEGIN:VTIMEZONE/gm) || []).length;

/** The zone of a text (the embedded path), compared by instants with another one over the matrix. */
function zoneOfText(text, tz) {
  const item = openItem(text, "event");
  assert.ok(item.ok && !item.readOnly, "opens editable");
  return item.zones.get(tz);
}

function checkMatrix(zn, off, note, label, { against } = {}) {
  const matrix = matrixWalls(off);
  let bad = 0;
  for (const c of matrix) {
    const want = refInstant(off, c.wallMs);
    const got = zn.instantFromWall(c.wallMs);
    if (got !== want) {
      bad++;
      if (bad <= 3) note(label, `${c.iso} (${c.why}): app ${stamp(got)} vs Intl ${stamp(want)}`);
    }
    if (against && against.instantFromWall(c.wallMs) !== got) note(label, `${c.iso}: served zone differs from the zone that was sent`);
  }
  if (bad > 3) note(label, `... ${bad} of ${matrix.length} wall times differ in all`);
  return matrix.length;
}

for (const zone of gateZones) {
  it(`GATE S13-own, ${zone}${zone === runnerZone() ? " (runner zone)" : ""}: our VTIMEZONE survives Radicale and the app reads Intl instants from it`, async (t) => {
    const off = intlOffset(zone);
    const col = await newCalendar(env, "tzo");
    const failures = [];
    const note = (kind, msg) => failures.push(`${kind}: ${msg}`);
    let reserialised = 0;
    const info = [];

    // (a) one event per wall time
    const walls = eventWalls(off);
    for (const [i, iso] of walls.entries()) {
      const { text, tzAdded } = newEventText(zone, iso);
      assert.equal(vtimezoneCount(text), 1, `${iso}: the sent text carries exactly one VTIMEZONE`);
      if (i === 0) info.push(...tzAdded.map((x) => `${x.form}${x.openEnded ? "" : ` to ${x.coveredThrough}`}`));
      const { served, item } = await putAndOpen(col, `e${i}`, text);
      if (!item.ok || item.readOnly) {
        note("event", `${iso} not editable (${item.reason || item.readOnlyReason})`);
        continue;
      }
      if (vtimezoneCount(served) !== 1) note("event", `${iso}: ${vtimezoneCount(served)} VTIMEZONEs served`);
      if (vtzLines(served) !== vtzLines(text)) reserialised++;
      const start = item.eventModel().start;
      // Radicale turns TZID=UTC into a plain UTC time (class `utc`, still the right instant)
      if (start.tzClass !== "embedded" && !(zone === "UTC" && start.tzClass === "utc")) note("class", `${iso}: ${start.tzClass} instead of embedded`);
      const want = refInstant(off, Date.parse(iso + "Z"));
      if (start.instant !== want) note("event", `${iso}: app ${stamp(start.instant)} vs Intl ${stamp(want)}`);
      const sent = zoneOfText(text, zone);
      const wall = Date.parse(iso + "Z");
      for (const k of [-3, -1, 0, 1, 3, 100, 2000]) {
        const w = wall + k * 15 * MIN;
        if (sent.instantFromWall(w) !== item.zones.get(zone).instantFromWall(w)) note("kept", `${iso}+${k * 15}min: served zone differs from the sent zone`);
      }
    }

    // (b) the 2024-2040 matrix against a zone served for a 17-year series
    const yearly = newEventText(zone, "2024-01-01T12:00:00", { rrule: "FREQ=YEARLY;COUNT=17" });
    const y = await putAndOpen(col, "yearly", yearly.text);
    assert.ok(y.item.ok && !y.item.readOnly);
    const zn = y.item.zones.get(zone);
    assert.equal(zn.tzClass, "embedded", "the served series keeps a usable VTIMEZONE");
    const matrixN = checkMatrix(zn, off, note, "matrix", { against: zoneOfText(yearly.text, zone) });
    const yearlyOcc = y.item.expand({ limit: 100 }).occurrences;
    if (yearlyOcc.length !== 17) note("yearly", `${yearlyOcc.length} occurrences instead of 17`);

    // (c) two 10-year weekly series
    let seriesCases = 0;
    for (const [label, time] of [["Sunday 02:30", "02:30:00"], ["Sunday 00:30", "00:30:00"]]) {
      const iso = `2026-01-04T${time}`;
      const { text } = newEventText(zone, iso, { rrule: "FREQ=WEEKLY;COUNT=520" });
      const { item } = await putAndOpen(col, `series-${time.slice(0, 2)}`, text);
      if (!item.ok || item.readOnly) {
        note("series", `${label} not editable`);
        continue;
      }
      const { occurrences, truncated } = item.expand({ limit: 2000 });
      if (truncated || occurrences.length !== 520) note("series", `${label}: ${occurrences.length} occurrences instead of 520`);
      let bad = 0;
      occurrences.forEach((o, n) => {
        seriesCases++;
        const wall = Date.parse(iso + "Z") + n * 7 * 86400000;
        if (o.start.wallMs !== wall) {
          bad++;
          if (bad <= 3) note("series", `${label} #${n}: wall ${stamp(o.start.wallMs)} instead of ${stamp(wall)}`);
        } else if (o.start.instant !== refInstant(off, wall)) {
          bad++;
          if (bad <= 3) note("series", `${label} #${n} ${stamp(wall)}: app ${stamp(o.start.instant)} vs Intl ${stamp(refInstant(off, wall))}`);
        }
      });
      if (bad > 3) note("series", `${label}: ${bad} of ${occurrences.length} occurrences differ in all`);
    }
    t.diagnostic(`${zone}: VTIMEZONE ${info[0] || "?"}; ${walls.length} events (${reserialised} with VTIMEZONE content changed by the server), ${matrixN} matrix walls, ${seriesCases} series occurrences, ${failures.length} problems`);
    assert.deepEqual(failures, [], `${zone} does not match Intl`);
  });
}

// ---------------------------------------------------------------------------
// (d) Europe/Paris five times, in different years: a fixed server answer every time

it("GATE S13-own, Europe/Paris x5: the same exact answer every time, in different event years", async (t) => {
  const zone = "Europe/Paris";
  const off = intlOffset(zone);
  const col = await newCalendar(env, "par");
  const failures = [];
  for (const [n, year] of [2024, 2027, 2031, 2036, 2040].entries()) {
    // last Sunday of October at 03:00 and 02:30 (the overlap), and the March gap, in that year
    const oct = new Date(Date.UTC(year, 9, 31));
    oct.setUTCDate(31 - oct.getUTCDay());
    const mar = new Date(Date.UTC(year, 2, 31));
    mar.setUTCDate(31 - mar.getUTCDay());
    const cases = [`${oct.toISOString().slice(0, 10)}T02:30:00`, `${oct.toISOString().slice(0, 10)}T03:00:00`, `${oct.toISOString().slice(0, 10)}T03:30:00`, `${mar.toISOString().slice(0, 10)}T02:30:00`, `${mar.toISOString().slice(0, 10)}T03:00:00`];
    for (const [k, iso] of cases.entries()) {
      const { text } = newEventText(zone, iso);
      const { item, served } = await putAndOpen(col, `p${n}-${k}`, text);
      assert.ok(item.ok && !item.readOnly);
      if (/DTSTART:\d{8}T040000/.test(served)) failures.push(`${year} ${iso}: served VTIMEZONE has an onset at 04:00`);
      const got = item.eventModel().start.instant;
      const want = refInstant(off, Date.parse(iso + "Z"));
      if (got !== want) failures.push(`${year} ${iso}: app ${stamp(got)} vs Intl ${stamp(want)}`);
    }
  }
  t.diagnostic(`Europe/Paris x5: ${failures.length} problems`);
  assert.deepEqual(failures, []);
});

// ---------------------------------------------------------------------------
// (e) the server keeps one tzinfo per TZID for its whole life: a foreign wrong VTIMEZONE seen FIRST must not matter

it("GATE S13-own: a wrong foreign VTIMEZONE seen first by the server does not change an item that carries ours", async (t) => {
  const zone = "Pacific/Auckland"; // used by no other test of this suite, so the server's registry for it is ours to poison
  const off = intlOffset(zone);
  const col = await newCalendar(env, "poison");
  const wrong = [
    "BEGIN:VCALENDAR", "VERSION:2.0", "PRODID:-//Example Corp//Calendar 1.0//EN",
    "BEGIN:VTIMEZONE", `TZID:${zone}`,
    "BEGIN:STANDARD", "DTSTART:19700405T030000", "TZOFFSETFROM:+1300", "TZOFFSETTO:+1200", "TZNAME:NZST", "RRULE:FREQ=YEARLY;BYMONTH=4;BYDAY=1SU", "END:STANDARD",
    "BEGIN:DAYLIGHT", "DTSTART:19700913T020000", "TZOFFSETFROM:+1200", "TZOFFSETTO:+1300", "TZNAME:NZDT", "RRULE:FREQ=YEARLY;BYMONTH=9;BYDAY=2SU", "END:DAYLIGHT",
    "END:VTIMEZONE", "BEGIN:VEVENT", "UID:poison-1@example.org", "DTSTAMP:20260101T000000Z", `DTSTART;TZID=${zone}:20260610T100000`, "SUMMARY:foreign", "END:VEVENT", "END:VCALENDAR",
  ].join("\r\n") + "\r\n";
  await env.client.putItem(`${col}poison.ics`, wrong, { create: true });
  const failures = [];
  // ours, after the poison, in a window the wrong rules (the transition dates are wrong) get wrong
  for (const [n, iso] of ["2026-09-27T02:30:00", "2026-09-27T03:30:00", "2027-04-04T02:30:00", "2027-04-04T03:30:00", "2030-04-07T02:30:00", "2030-09-29T02:30:00"].entries()) {
    const { text } = newEventText(zone, iso);
    const { item } = await putAndOpen(col, `ok-${n}`, text);
    assert.ok(item.ok && !item.readOnly);
    const got = item.eventModel().start.instant;
    const want = refInstant(off, Date.parse(iso + "Z"));
    if (got !== want) failures.push(`${iso}: app ${stamp(got)} vs Intl ${stamp(want)}`);
  }
  // what the server would have done for a bare TZID after the poison (documentation of the cause, not a requirement)
  const bare = ["BEGIN:VCALENDAR", "VERSION:2.0", "PRODID:-//Example Corp//Calendar 1.0//EN", "BEGIN:VEVENT", "UID:poison-2@example.org", "DTSTAMP:20260101T000000Z", `DTSTART;TZID=${zone}:20260920T033000`, "SUMMARY:bare", "END:VEVENT", "END:VCALENDAR"].join("\r\n") + "\r\n";
  const b = await putAndOpen(col, "bare", bare);
  const bi = b.item.eventModel().start.instant;
  t.diagnostic(`bare TZID after the poison: the server's VTIMEZONE gives ${stamp(bi)}, Intl ${stamp(refInstant(off, Date.parse("2026-09-20T03:30:00Z")))} (different = the server reused the foreign zone it saw first)`);
  assert.deepEqual(failures, []);
});
